'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm');
function setup(reduced=false){const frames=new Map(),listeners=new Map();let time=0,serial=0;const document={activeElement:null},picked=[];const window={matchMedia:()=>({matches:reduced,addEventListener(){}}),performance:{now:()=>time},requestAnimationFrame(fn){frames.set(++serial,fn);return serial},cancelAnimationFrame(id){frames.delete(id)}};const c={window,document};for(const file of ['deck-motion.js','diagrams-compass.js'])vm.runInNewContext(fs.readFileSync(file,'utf8'),c);const strip={dataset:{},scrollLeft:0,clientWidth:320,scrollWidth:1870,addEventListener:(name,fn)=>listeners.set(name,fn),getBoundingClientRect:()=>({left:10,width:320}),setPointerCapture(id){this.captured=id},hasPointerCapture(id){return this.captured===id},releasePointerCapture(){this.captured=null}};const buttons=new Map(Array.from('ABCDEFGHIJKLMNOPQRSTUVWXYZ',(letter,i)=>{const classes=new Set(),attrs={};const node={style:{},disabled:false,dataset:{letter},classList:{toggle(key,on){on?classes.add(key):classes.delete(key)},contains:key=>classes.has(key)},setAttribute:(k,v)=>attrs[k]=v,removeAttribute:k=>delete attrs[k],getAttribute:k=>attrs[k],getBoundingClientRect:()=>({left:144+Number(node.style.transform.match(/[-\d.]+/)[0]),width:52}),focus(){document.activeElement=node}};return [letter,node]}));const api=window.PhoenixDiagramCompass.create({strip,buttons,onPick:letter=>picked.push(letter)});function fire(name,extra={}){let prevented=false;listeners.get(name)?.({isPrimary:true,button:0,pointerId:1,clientX:200,clientY:100,timeStamp:time,preventDefault(){prevented=true},stopImmediatePropagation(){prevented=true},...extra});return prevented;}return {api,strip,buttons,picked,document,fire,frames,frame(dt){time+=dt;const list=[...frames.values()];frames.clear();list.forEach(fn=>fn(time))}};}
test('current letter centers beneath a fixed pointer, including A and Z',()=>{const x=setup();for(const letter of ['A','C','Z']){x.api.sync(letter);const b=x.buttons.get(letter);assert.equal(b.getBoundingClientRect().left+26,170);assert.equal(b.getAttribute('aria-current'),'true')}assert.equal(x.api.position(),-62)});
test('letter drag browses independently and leaves current card identity alone',()=>{const x=setup();x.api.sync('C');const before=x.api.position();x.fire('pointerdown');x.fire('pointermove',{clientX:140,timeStamp:16});assert.ok(x.api.position()>before);assert.deepEqual(x.picked,[]);assert.equal(x.buttons.get('C').getAttribute('aria-current'),'true');x.fire('pointercancel')});
test('flick glides without snapping, first tap stops, next deliberate tap picks a letter',()=>{const x=setup();x.api.sync('C');x.fire('pointerdown');x.fire('pointermove',{clientX:160,timeStamp:16});x.fire('pointerup',{timeStamp:20});const before=x.api.position();x.frame(16);assert.ok(x.api.position()>before);x.fire('pointerdown');x.fire('pointerup');assert.equal(x.fire('click'),true);assert.deepEqual(x.picked,[]);x.fire('pointerdown');x.fire('pointerup');if(!x.fire('click'))x.buttons.get('D').onclick();assert.deepEqual(x.picked,['D'])});
test('keyboard browsing skips unavailable letters and never selects until activation',()=>{const x=setup();x.buttons.get('B').disabled=true;x.buttons.get('A').focus();x.fire('keydown',{key:'ArrowRight'});assert.equal(x.document.activeElement,x.buttons.get('C'));assert.deepEqual(x.picked,[]);x.buttons.get('C').onclick();assert.deepEqual(x.picked,['C'])});
test('return restores independent letter position without moving any card',()=>{const x=setup();x.api.sync('C');x.api.restore(780);const saved=x.api.position();x.api.sync('C',{center:false});x.api.restore(saved);assert.equal(x.api.position(),780);assert.deepEqual(x.picked,[]);assert.equal(x.buttons.get('C').getAttribute('aria-current'),'true')});
test('looping positions remain usable with empty filters and reduced motion',()=>{const x=setup(true);x.api.restore(-20);assert.equal(x.api.position(),-20);x.api.restore(Infinity);assert.equal(x.api.position(),0);for(const button of x.buttons.values())button.disabled=true;x.api.sync('C');assert.equal(x.buttons.get('C').getAttribute('aria-current'),undefined);x.buttons.get('C').onclick();assert.deepEqual(x.picked,[])});
test('many full loops retain one logical identity and choose the nearest cycle on selection',()=>{const x=setup();x.api.restore(26*62*1000+25*62);x.api.sync('C');assert.equal(x.api.position(),(26*1001+2)*62);assert.equal(x.buttons.size,26);assert.equal(x.buttons.get('C').getBoundingClientRect().left+26,170);assert.deepEqual(x.picked,[])});
function filterTo(x,letters){for(const [letter,button]of x.buttons)button.disabled=!letters.includes(letter);}
test('filter membership hides absent letters and compacts visible alphabetical spacing',()=>{const x=setup();filterTo(x,'ACV');x.api.sync('C');assert.equal(x.api.letters(),'ACV');assert.equal(x.buttons.get('B').hidden,true);assert.equal(x.buttons.get('A').hidden,false);assert.equal(x.buttons.get('C').getBoundingClientRect().left+26,170);assert.equal(x.buttons.get('V').getBoundingClientRect().left-x.buttons.get('C').getBoundingClientRect().left,62);assert.equal(x.strip.dataset.canBrowse,'false')});
test('a lone matching letter stays centered through drag, flick, wheel and restore',()=>{const x=setup();filterTo(x,'V');x.api.sync('V');x.fire('pointerdown');x.fire('pointermove',{clientX:120,timeStamp:16});x.fire('pointerup',{timeStamp:20});x.frame(16);x.fire('wheel',{deltaX:400});x.api.restore(1206);assert.equal(x.api.position(),0);assert.equal(x.buttons.get('V').getBoundingClientRect().left+26,170);assert.equal(x.api.letters(),'V');assert.deepEqual(x.picked,[])});
test('empty filters produce no active letters and repopulate cleanly after a filter change',()=>{const x=setup();filterTo(x,'');x.api.sync('');assert.equal(x.api.letters(),'');assert.equal(x.strip.dataset.letterCount,'0');assert.ok([...x.buttons.values()].every(b=>b.hidden));filterTo(x,'CGV');x.api.sync('G');assert.equal(x.api.letters(),'CGV');assert.equal(x.buttons.get('G').hidden,false);assert.equal(x.buttons.get('G').getBoundingClientRect().left+26,170)});
test('a filtered overflowing alphabet loops without gaps and preserves its independent position',()=>{const x=setup();filterTo(x,'ACGMRV');x.api.sync('V');const v=x.buttons.get('V');assert.equal(v.getBoundingClientRect().left+26,170);x.api.restore(7*62+17);const saved=x.api.position();x.api.sync('V',{center:false});assert.equal(x.api.position(),saved);assert.equal(x.api.letters(),'ACGMRV');assert.equal(x.strip.dataset.canBrowse,'true');assert.equal(x.buttons.get('B').hidden,true);x.buttons.get('B').onclick();assert.deepEqual(x.picked,[])});
